57	/**
58	 * Creates the org row. The slug is de-duplicated here rather than in the
59	 * service so a race on the unique index still resolves to a usable slug.
60	 */
61	export async function insertOrg(
62	  input: CreateOrganizationInput,
63	  ownerId: UserId,
64	): Promise<Organization> {
65	  const taken = await listTakenOrgSlugs(input.slug);
66	  const slug = uniqueSlug(input.slug, taken);
67	  const stamp = toIsoTimestamp(new Date());
