88	export async function updateOrg(
89	  orgId: OrgId,
90	  patch: UpdateOrganizationInput,
91	): Promise<Organization> {
92	  const current = await findOrgById(orgId);
93	  if (!current) throw new Error(`Organization ${orgId} not found`);
94	
95	  const settings = { ...current.settings, ...(patch.settings ?? {}) };
96	
97	  const row = getDb()
98	    .update(organizations)
99	    .set({
100	      ...(patch.name === undefined ? {} : { name: patch.name }),
101	      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
102	      defaultIssueStatus: settings.defaultIssueStatus,
103	      allowPublicProjects: settings.allowPublicProjects,
104	      requireTwoFactor: settings.requireTwoFactor,
105	      digestHourUtc: settings.digestHourUtc,
106	      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
107	      updatedAt: toIsoTimestamp(new Date()),
108	    })
109	    .where(eq(organizations.id, orgId))
110	    .returning()
111	    .get();
112	
113	  return toOrganization(row);
114	}
