116	export async function archiveOrg(orgId: OrgId): Promise<Organization> {
117	  const row = getDb()
118	    .update(organizations)
119	    .set(archivePatch())
120	    .where(eq(organizations.id, orgId))
121	    .returning()
122	    .get();
123	
124	  if (!row) throw new Error(`Organization ${orgId} not found`);
125	  return toOrganization(row);
126	}
