128	/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
129	export async function listTakenOrgSlugs(
130	  prefix: string,
131	): Promise<readonly string[]> {
132	  const rows = getDb()
133	    .select({ slug: organizations.slug })
134	    .from(organizations)
135	    .where(like(organizations.slug, `${prefix}%`))
136	    .all();
137	  return rows.map((row) => row.slug);
138	}
