2	 * Downgrades organizations whose trial ended and emits `billing.plan_changed`.
3	 *
4	 * Must call (do not reimplement): emit, getPlanLimits
5	 */
6	import { getPlanLimits } from "@/config/plan-limits";
7	import { emit } from "@/lib/event-bus";
8	import { createLogger } from "@/lib/logger";
9	import * as subscriptionRepo from "@/server/repositories/subscription-repository";
10	import * as usageRepo from "@/server/repositories/usage-repository";
11	import { toIsoTimestamp } from "@/types/common";
12	import { runJob } from "./types";
13	import type { JobResult } from "@/server/jobs/types";
14	import type { OrgId } from "@/types/common";
15	
16	/** Where an expired trial lands. */
17	const FALLBACK_PLAN = "free" as const;
18	
19	const logger = createLogger("trial-expiry-job");
20	
21	/**
22	 * Moves expired trials down to the free plan and announces the change so the
23	 * audit log and any webhook subscriber see it.
24	 *
25	 * A tenant that outgrew the free limits during the trial is left alone and
26	 * logged instead: silently downgrading them would put their workspace over
27	 * quota, and every subsequent write would fail with no explanation.
28	 */
29	export async function runTrialExpiryJob(now: Date): Promise<JobResult> {
30	  return runJob("trial-expiry", async (result) => {
31	    const stamp = toIsoTimestamp(now);
32	    const expiring = await subscriptionRepo.listTrialsEndingBefore(stamp);
33	    const freeLimits = getPlanLimits(FALLBACK_PLAN);
